  match lst with
  | [] => none
  | x :: xs =>
      let rec find (rem : List Int) (idx : Nat) : Option Nat :=
        match rem with
        | [] => none
        | y :: ys =>
            if x + y = target then
              some idx
            else
              find ys (idx + 1)
      let jOpt := find xs (start + 1)
      if jOpt = some j then some (start, j)
      else findPair xs (start + 1)
